/* C API of the Rust port of `wrappers.c`, generated by rust-anything. */
#ifndef WRAPPERS_RS_H
#define WRAPPERS_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

unsigned int num_possible_cpus(void);
uint64_t wrap_rht_seq(uint64_t seed, int64_t nops_i, int64_t fail_i);
uint64_t wrap_rhlt_seq(uint64_t seed, int64_t nops_i, int64_t fail_i);
uint64_t wrap_rht_walk(uint64_t seed, int64_t n_i, int64_t fail_i);
uint64_t wrap_rht_elastic(uint64_t seed, int64_t n_i, int64_t fail_i);
uint64_t wrap_bkl(uint64_t seed, int64_t n_i, int64_t fail_i);

/* The same functions under `rust_anything_` names, for shadow runs. */
unsigned int rust_anything_num_possible_cpus(void);
uint64_t rust_anything_wrap_rht_seq(uint64_t seed, int64_t nops_i, int64_t fail_i);
uint64_t rust_anything_wrap_rhlt_seq(uint64_t seed, int64_t nops_i, int64_t fail_i);
uint64_t rust_anything_wrap_rht_walk(uint64_t seed, int64_t n_i, int64_t fail_i);
uint64_t rust_anything_wrap_rht_elastic(uint64_t seed, int64_t n_i, int64_t fail_i);
uint64_t rust_anything_wrap_bkl(uint64_t seed, int64_t n_i, int64_t fail_i);

#endif /* WRAPPERS_RS_H */
